pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // any newOwner is admissible, including the zero address (domain kept wide)
        address caller = c.owner();
        vm.prank(caller);
        bool reverted = false;
        bool returned = false;
        try c.setOwner(newOwner) returns (bool ret) {
            returned = ret;
        } catch {
            reverted = true;
        }
        // Rule: a call by the owner to setOwner never reverts and ALWAYS returns true,
        // for every argument — including address(0).
        assertTrue(!reverted && returned);
    }
}

